window.B0B_INTRO_CHAPTERS=[{"id": "I", "title": "The record", "year": "2011", "at": 0.0, "end": 17.66, "map": false, "lines": [{"text": "Nuremberg, 1945. The prosecution argued from documents, not rumour.", "at": 0.35, "end": 5.98}, {"text": "The record keeps arriving the same way: the Pentagon Papers, the 9/11 Commission, the Senate’s torture report.", "at": 6.43, "end": 12.914}, {"text": "Show the record. Say where it came from. Let the reader test it.", "at": 13.364, "end": 16.961}]}, {"id": "II", "title": "The instrument", "year": "2025", "at": 17.66, "end": 37.05, "map": false, "lines": [{"text": "Washington, 1947. A committee of Congress turned the cameras on citizens.", "at": 18.01, "end": 23.445}, {"text": "Now the cameras sit on poles and rooftops, and nobody has to call a hearing.", "at": 23.895, "end": 28.145}, {"text": "An inquiry and a hunt look the same from outside. The test: could the finding have come out the other way?", "at": 28.595, "end": 34.223}]}, {"id": "III", "title": "The capability", "year": "2015", "at": 37.05, "end": 55.825, "map": false, "lines": [{"text": "Enewetak, 1952. The capability arrives before the argument about what it is for.", "at": 37.4, "end": 43.497}, {"text": "So does the data centre, the drone and the supercomputer.", "at": 43.947, "end": 47.545}, {"text": "A document can establish a capability. It does not establish a use. Secrecy is evidence of nothing about what is hidden.", "at": 47.995, "end": 55.126}]}, {"id": "IV", "title": "The overhead", "year": "2021", "at": 55.825, "end": 71.745, "map": false, "lines": [{"text": "1958. The first American satellite carried a cosmic-ray counter, not a camera.", "at": 56.175, "end": 61.576}, {"text": "The cameras came in 1960, as CORONA, and stayed classified for thirty-five years.", "at": 62.026, "end": 67.594}, {"text": "Now the night side of the planet is a public photograph.", "at": 68.044, "end": 71.028}]}, {"id": "V", "title": "The annotation", "year": "2003", "at": 71.745, "end": 92.246, "map": false, "lines": [{"text": "October 1962. A reconnaissance photograph became evidence when somebody labelled it, and the missiles were there.", "at": 72.095, "end": 79.712}, {"text": "February 2003, the same Council: labelled slides again. This time the weapons were not.", "at": 80.162, "end": 86.558}, {"text": "The label is the claim. Check it, including every caption in this film.", "at": 87.008, "end": 91.548}]}, {"id": "VI", "title": "The public", "year": "2020", "at": 92.246, "end": 112.67, "map": false, "lines": [{"text": "1963. 1967. 2003. 2011. 2020. The placards change; the shape of the crowd does not.", "at": 92.596, "end": 101.854}, {"text": "A crowd is testimony: evidence of an experience, never, by itself, evidence of a cause.", "at": 102.304, "end": 108.865}, {"text": "The newsreel filmed the counter-demonstrators too.", "at": 109.315, "end": 111.968}]}, {"id": "VII", "title": "The inquiry", "year": "2012", "at": 112.67, "end": 129.131, "map": false, "lines": [{"text": "The transcripts, 1974. The Church Committee, 1975. Iran-Contra, 1987.", "at": 113.02, "end": 120.517}, {"text": "The inquiry always comes afterwards.", "at": 120.967, "end": 123.66}, {"text": "Everything in this report arrived the same way: late, in public, and on the record.", "at": 124.11, "end": 128.429}]}, {"id": "VIII", "title": "The ledger", "year": "2026", "at": 129.131, "end": 158.061, "map": false, "lines": [{"text": "{TOTAL} documented sites. Twenty-five sections.", "at": 131.031, "end": 136.248}, {"text": "Every source named. Every tier stated.", "at": 136.698, "end": 139.325}, {"text": "The specimens it could not prove, killed on its own page.", "at": 139.775, "end": 143.381}, {"text": "The authority of a document does not come from what it alleges.", "at": 143.831, "end": 147.024}, {"text": "It comes from what it refuses to allege.", "at": 147.474, "end": 149.97}, {"text": "τετέλεσται — it has been completed, and remains so.", "at": 150.42, "end": 154.861}]}];
window.B0B_INTRO_REEL_DUR=158.061;
